# Function to calculate the total number of digits in the sequence of digits formed by the perfect squares from 1 to n^2
def count_digits_in_sequence(n):
    total_digits = 0

    # Count digits for numbers 1 to 31
    for i in range(1, 32):
        if i * i <= n:
            total_digits += len(str(i * i))
        else:
            break
    
    # Count digits for numbers 32 to 50
